import functools
from typing import ForwardRef, List
from fastapi import FastAPI
from fastapi.routing import APIRoute
from fastapi.dependencies.utils import get_typed_signature
import inspect

class MyModel:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def test_wrapped_method_type_inference():
    app = FastAPI()

    @wrapper
    def endpoint(item: "MyModel"):
        return {"message": "hello"}

    app.add_api_route("/test", endpoint)

    # This should not raise NameError
    sig = get_typed_signature(endpoint)
    print(sig)
    assert sig.parameters["item"].annotation is MyModel

if __name__ == "__main__":
    try:
        test_wrapped_method_type_inference()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

