    app.add_api_route("/test", endpoint)
    print("app.add_api_route test passed!")

if __name__ == "__main__":
    try:
        test_wrapped_method_type_inference()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
