import functools
from typing import ForwardRef, List
from fastapi import FastAPI
from fastapi.dependencies.utils import get_typed_signature
import inspect
from pydantic import BaseModel

class MyModel(BaseModel):
    name: str

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def test_wrapped_method_type_inference():
    # We need to define the model in a way that it's not in the same globals as the wrapped function
    # to truly test the __globals__ issue.

    def create_endpoint():
        class LocalModel(BaseModel):
            name: str

        @wrapper
        def endpoint(item: "LocalModel"):
            return {"message": "hello"}

        return endpoint, LocalModel

    endpoint, LocalModel = create_endpoint()

    # The wrapped function's __globals__ will be the globals of the 'wrapper' function's 
    # definition site, or the 'wrapped' function's definition site.
    # Actually, functools.wraps(func) copies __annotations__, but not __globals__.
    # The 'wrapped' function has its own __globals__.

    sig = get_typed_signature(endpoint)
    print(f"Signature: {sig}")
    assert sig.parameters["item"].annotation is LocalModel
    print("Test passed!")

if __name__ == "__main__":
    try:
        test_wrapped_method_type_inference()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

